function localStore(key,initial=[]){try{const raw=localStorage.getItem(`nexoflow-${key}`);if(raw)return JSON.parse(raw);localStorage.setItem(`nexoflow-${key}`,JSON.stringify(initial));return initial}catch{return window.__nexoflowMemory?.[key]||initial}}
function localSave(key,value){try{localStorage.setItem(`nexoflow-${key}`,JSON.stringify(value))}catch{window.__nexoflowMemory=window.__nexoflowMemory||{};window.__nexoflowMemory[key]=value}}
async function localApi(path,options={}){const method=options.method||'GET',body=options.body?JSON.parse(options.body):{},query=new URLSearchParams(path.split('?')[1]||''),route=path.split('?')[0];path=route;let products=localStore('products',[{id:'p1',sku:'FON-2041',name:'Fone Bluetooth Wave Pro',category:'Eletrônicos',price:249.9,cost:130,stock:34,min_stock:8},{id:'p2',sku:'GAR-1180',name:'Garrafa Térmica Inox 750ml',category:'Acessórios',price:89.9,cost:42,stock:4,min_stock:8},{id:'p3',sku:'MOC-0902',name:'Mochila Urbana Compact',category:'Bolsas',price:179,cost:88,stock:21,min_stock:5}]);let sales=localStore('sales'),finance=localStore('finance'),movements=localStore('movements'),xmls=localStore('xmls'),settings=localStore('settings',{}),operations=localStore('operations'),locations=localStore('locations',[{id:'loc-main',name:'Loja Centro'},{id:'loc-north',name:'Filial Norte'}]),balances=localStore('stock_locations',products.map(p=>({product_id:p.id,location_id:'loc-main',quantity:p.stock})));const err=(message)=>{throw new Error(message)};if(path==='/health')return{ok:true,database:'Armazenamento deste navegador',app:'NexoFlow'};if(path==='/dashboard')return{products:products.length,lowStock:products.filter(p=>p.stock<=p.min_stock).length,sales:sales.reduce((s,x)=>s+x.total,0),orders:sales.length,financeOpen:finance.filter(x=>x.status==='open').reduce((s,x)=>s+x.amount,0)};if(path==='/products'&&method==='GET')return products;if(path==='/locations'&&method==='GET')return locations;if(path==='/stock-by-location'&&method==='GET')return balances.map(b=>({...b,product:products.find(p=>p.id===b.product_id)?.name,location:locations.find(l=>l.id===b.location_id)?.name}));if(path==='/sales'&&method==='GET')return sales;if(path.startsWith('/sales/')&&path.endsWith('/convert')&&method==='POST'){const sale=sales.find(x=>x.id===path.split('/').at(-2)&&x.status==='quote');if(!sale)err('Este orçamento não está mais aguardando aprovação.');for(const row of sale.items||[]){const prod=products.find(p=>p.id===row.product_id);if(!prod||prod.stock<row.quantity)err(`Estoque insuficiente para ${prod?.name||'produto'}.`)}for(const row of sale.items||[]){const prod=products.find(p=>p.id===row.product_id);prod.stock-=row.quantity;const bal=balances.find(b=>b.product_id===prod.id&&b.location_id==='loc-main');if(bal)bal.quantity-=row.quantity;movements.unshift({id:crypto.randomUUID(),product:prod.name,kind:'sale',quantity:-row.quantity,note:`Orçamento #${sale.number} convertido`})}sale.status='paid';localSave('products',products);localSave('stock_locations',balances);localSave('movements',movements);localSave('sales',sales);return{ok:true,number:sale.number}}if(path==='/finance'&&method==='GET')return finance;if(path==='/movements'&&method==='GET')return movements;if(path==='/xml'&&method==='GET')return xmls;if(path==='/operations'&&method==='GET')return operations.filter(x=>!query.get('kind')||x.kind===query.get('kind'));if(path==='/operations'&&method==='POST'){const op={...body,id:crypto.randomUUID(),status:body.status||'open',created_at:new Date().toISOString()};operations.unshift(op);localSave('operations',operations);return{id:op.id}}if(path.startsWith('/operations/')&&method==='PUT'){const op=operations.find(x=>x.id===path.split('/').pop());if(op)op.status=body.status||'done';localSave('operations',operations);return{ok:true}}if(path.startsWith('/settings/')&&method==='GET')return settings[path.split('/').pop()]||{};if(path.startsWith('/settings/')&&method==='POST'){settings[path.split('/').pop()]=body;localSave('settings',settings);return{ok:true}}if(path==='/products'&&method==='POST'){if(products.some(p=>p.sku===body.sku))err('Este SKU já está cadastrado.');const p={...body,id:crypto.randomUUID()};products.push(p);balances.push({product_id:p.id,location_id:'loc-main',quantity:Number(p.stock)||0});localSave('products',products);localSave('stock_locations',balances);return{id:p.id}}if(path==='/sales'&&method==='POST'){let total=0;for(const item of body.items||[]){const p=products.find(x=>x.id===item.product_id||x.sku===item.sku);if(!p)err('Produto não encontrado no catálogo.');if(body.status!=='quote'&&p.stock<item.quantity)err(`Estoque insuficiente para ${p.name}.`);total+=(Number(item.unit_price)||p.price)*item.quantity}const number=sales.length+1;if(body.status!=='quote')for(const item of body.items){const p=products.find(x=>x.id===item.product_id||x.sku===item.sku);p.stock-=item.quantity;const bal=balances.find(b=>b.product_id===p.id&&b.location_id==='loc-main');if(bal)bal.quantity-=item.quantity;movements.push({id:crypto.randomUUID(),product:p.name,kind:'sale',quantity:-item.quantity,note:`Venda #${number}`})}const s={id:crypto.randomUUID(),number,customer:body.customer||'Consumidor final',channel:body.channel||'PDV',items:(body.items||[]).map(i=>({product_id:i.product_id,quantity:i.quantity})),total,status:body.status==='quote'?'quote':'paid',created_at:new Date().toISOString()};sales.unshift(s);localSave('products',products);localSave('stock_locations',balances);localSave('sales',sales);localSave('movements',movements);return{id:s.id,number,total}}if(path==='/movements'&&method==='POST'){const p=products.find(x=>x.id===body.product_id);if(!p)err('Produto não encontrado.');const delta=body.kind==='in'?Number(body.quantity):-Number(body.quantity);if(p.stock+delta<0)err('A movimentação deixaria o estoque negativo.');p.stock+=delta;let bal=balances.find(b=>b.product_id===p.id&&b.location_id==='loc-main');if(!bal){bal={product_id:p.id,location_id:'loc-main',quantity:0};balances.push(bal)}bal.quantity+=delta;movements.unshift({...body,id:crypto.randomUUID(),product:p.name,quantity:delta});localSave('products',products);localSave('stock_locations',balances);localSave('movements',movements);return{ok:true}}if(path==='/transfers'&&method==='POST'){const p=products.find(x=>x.id===body.product_id),src=locations.find(l=>l.name===body.source),dst=locations.find(l=>l.name===body.destination),qty=Number(body.quantity);if(!p||!src||!dst||src.id===dst.id||qty<=0)err('Confira produto, quantidade e lojas.');const sb=balances.find(b=>b.product_id===p.id&&b.location_id===src.id);if(!sb||sb.quantity<qty)err(`Saldo insuficiente em ${src.name}.`);sb.quantity-=qty;let dbal=balances.find(b=>b.product_id===p.id&&b.location_id===dst.id);if(!dbal){dbal={product_id:p.id,location_id:dst.id,quantity:0};balances.push(dbal)}dbal.quantity+=qty;movements.unshift({id:crypto.randomUUID(),product:p.name,kind:'transfer',quantity:qty,note:`${src.name} → ${dst.name}`});localSave('stock_locations',balances);localSave('movements',movements);return{ok:true}}if(path==='/finance'&&method==='POST'){const amount=Number(body.amount);if(!amount||amount<=0)err('Informe valor maior que zero.');const x={...body,id:crypto.randomUUID(),status:'open',created_at:new Date().toISOString()};finance.unshift(x);localSave('finance',finance);return{id:x.id}}if(path.startsWith('/finance/')&&method==='PUT'){const x=finance.find(r=>r.id===path.split('/').pop());if(x)x.status=body.status||'paid';localSave('finance',finance);return{ok:true}}if(path.startsWith('/finance/')&&method==='DELETE'){finance=finance.filter(x=>x.id!==path.split('/').pop());localSave('finance',finance);return{ok:true}}if(path==='/xml/read'&&method==='POST'){const doc=new DOMParser().parseFromString(body.xml,'text/xml');if(doc.querySelector('parsererror'))err('O arquivo não parece ser um XML válido.');const get=(root,name)=>[...root.getElementsByTagName('*')].find(el=>el.localName===name)?.textContent?.trim()||'';const items=[...doc.getElementsByTagName('*')].filter(el=>el.localName==='det').map(det=>{const all=[...det.getElementsByTagName('*')],v=n=>all.find(x=>x.localName===n)?.textContent?.trim()||'';return{name:v('xProd'),sku:v('cProd'),ean:v('cEAN'),quantity:v('qCom'),unit_price:v('vUnCom'),total:v('vProd')}});const payload={supplier:get(doc,'xNome'),number:get(doc,'nNF'),total:Number(get(doc,'vNF'))||0,items};const record={id:crypto.randomUUID(),filename:body.filename,payload,status:'review'};xmls.unshift(record);localSave('xmls',xmls);return{id:record.id,payload}}if(path==='/xml/process'&&method==='POST'){const record=xmls.find(x=>x.id===body.id);if(!record)err('Nota não encontrada.');for(const item of body.items){const p=products.find(x=>x.id===item.product_id);if(!p)err('Vincule o produto da nota ao catálogo.');p.stock+=Number(item.quantity);movements.unshift({id:crypto.randomUUID(),product:p.name,kind:'in',quantity:Number(item.quantity),note:`Entrada XML ${record.payload.number}`})}if(body.total)finance.unshift({id:crypto.randomUUID(),description:`Compra NF ${record.payload.number} · ${record.payload.supplier}`,kind:'pay',due_date:body.due_date,category:'Fornecedores',amount:Number(body.total),status:'open'});record.status='processed';for(const item of body.items){const p=products.find(x=>x.id===item.product_id);const bal=balances.find(x=>x.product_id===p?.id&&x.location_id==='loc-main');if(bal)bal.quantity+=Number(item.quantity)}localSave('products',products);localSave('stock_locations',balances);localSave('finance',finance);localSave('movements',movements);localSave('xmls',xmls);return{ok:true}}err('Operação não disponível no modo local.')}
async function api(path,options={}){if(fileMode&&(/^\/(users|access-logs|auth\/|admin-state)/.test(path)))throw new Error('Para criar e administrar acessos com senha protegida, abra o sistema pelo iniciar.bat.');if(fileMode)return localApi(path,options);const response=await fetch(`/api${path}`,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await response.json().catch(()=>({error:'Resposta inválida do servidor'}));if(response.status===401&&!['/users','/access-logs'].includes(path)){location.href='/login.html';throw new Error('Sua sessão expirou. Entre novamente.')}if(!response.ok)throw new Error(data.error||'Não foi possível concluir a operação');return data}
