function renderFeatureCatalog(){const root=document.getElementById('featureGroups');if(!root)return;root.innerHTML=featureCatalog.map((group,index)=>`<section class="feature-group"><button class="feature-group-heading" aria-expanded="${index===0?'true':'false'}"><span class="feature-group-icon ${group.color}">${group.icon}</span><span class="feature-group-title"><strong>${group.name}</strong><small>${group.desc}</small></span><span class="feature-group-count">${group.features.length} recursos</span><span class="feature-group-chevron">⌄</span></button><div class="feature-card-grid" ${index===0?'':'hidden'}>${group.features.map(item=>`<article class="feature-card"><div class="feature-card-top"><span class="feature-card-icon ${group.color}">${group.icon}</span>${item[2]?'<span class="popular-badge">Mais usada</span>':''}</div><h3>${item[0]}</h3><p>${item[1]}</p><button class="feature-more" data-feature-page="${item[3]}">Saiba mais <span>→</span></button></article>`).join('')}</div></section>`).join('');root.querySelectorAll('.feature-group-heading').forEach(btn=>btn.addEventListener('click',()=>{const panel=btn.nextElementSibling;const open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open));panel.hidden=open}));root.querySelectorAll('[data-feature-page]').forEach(btn=>btn.addEventListener('click',()=>goToPage(btn.dataset.featurePage)))}
renderFeatureCatalog();
