  const showLogin=message=>{const layout=container.querySelector('.admin-access-layout');layout.innerHTML=`<section class="panel admin-login-panel"><div class="panel-header"><div><h2>Confirme o acesso administrativo</h2><p>${escapeHtml(message)}</p></div></div><form class="admin-access-form" id="adminLoginForm"><label class="form-field"><span>E-mail</span><input name="email" required type="email" autocomplete="username"/></label><label class="form-field"><span>Senha</span><input name="password" required type="password" autocomplete="current-password"/></label><div class="form-actions"><button class="button button-primary">Entrar na administração</button><a href="sales-page.html" class="text-link">Página comercial</a></div><p class="admin-security-note" data-login-error></p></form></section>`;layout.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{await api('/auth/login',{method:'POST',body:JSON.stringify(body)});await renderUsersAdmin(container)}catch(err){layout.querySelector('[data-login-error]').textContent=err.message}})};
