async function refreshFinance(){try{const rows=await api('/finance');const body=document.querySelector('#page-finance tbody');if(body)body.innerHTML=rows.map(x=>`<tr><td><strong>${escapeHtml(x.description)}</strong></td><td>${x.kind==='receive'?'A receber':'A pagar'}</td><td>${escapeHtml(x.due_date||'—')}</td><td>${escapeHtml(x.category)}</td><td class="money">${money(x.amount)}</td><td><button class="status-pill ${x.status==='paid'?'status-paid':'status-pending'}" data-finance-paid="${x.id}">● ${x.status==='paid'?'Pago':'Em aberto'}</button></td></tr>`).join('')||'<tr><td colspan="6">Nenhum lançamento cadastrado.</td></tr>';body?.querySelectorAll('[data-finance-paid]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/finance/${b.dataset.financePaid}`,{method:'PUT',body:JSON.stringify({status:'paid'})});await refreshFinance();showToast('Lançamento marcado como pago')}catch(e){showToast(e.message)}}))}catch(e){}}
async function refreshSales(){try{const rows=await api('/sales'),body=document.querySelector('#page-sales tbody');if(!body)return;body.innerHTML=rows.map(x=>`<tr><td><strong class="order-id">#NF-${x.number}</strong></td><td>${escapeHtml(x.customer)}</td><td>${new Date(x.created_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</td><td>${escapeHtml(x.channel)}</td><td class="money">${money(x.total)}</td><td><span class="status-pill ${x.status==='quote'?'status-pending':'status-paid'}">● ${x.status==='quote'?'Orçamento':'Pago'}</span>${x.status==='quote'?` <button class="mini-action" data-convert-quote="${x.id}">Aprovar e converter</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum pedido registrado. Clique em Novo pedido para começar.</td></tr>';body.querySelectorAll('[data-convert-quote]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/sales/${btn.dataset.convertQuote}/convert`,{method:'POST',body:JSON.stringify({})});showToast('Orçamento aprovado · venda criada e estoque atualizado');await refreshSales();await refreshProductTables()}catch(err){showToast(err.message)}}))}catch(e){}}
async function refreshOperationHistory(kind,container){try{const rows=await api(`/operations?kind=${encodeURIComponent(kind)}`),root=container.querySelector('[data-operation-history]');if(!root)return;root.innerHTML=rows.slice(0,8).map(x=>`<div class="operation-history-row"><span><strong>${escapeHtml(x.title)}</strong><small>${new Date(x.created_at).toLocaleString('pt-BR')} · ${escapeHtml(x.status)}${kind==='quote'&&x.payload?.total!==undefined?' · total '+money(x.payload.total):''}</small></span>${(x.status==='open'||x.status==='pending')&&kind!=='signature'?`<button class="button button-light" data-operation-done="${x.id}" data-operation-kind="${kind}">${kind==='rental'?'Registrar devolução':kind==='shipping'?'Despachar':'Concluir'}</button>`:''}</div>`).join('')||'<p class="empty-state">Ainda não há registros neste módulo.</p>';root.querySelectorAll('[data-operation-done]').forEach(btn=>btn.addEventListener('click',async()=>{try{const item=rows.find(x=>x.id===btn.dataset.operationDone),payload=item?.payload;if(kind==='rental'&&payload?.product_id)await api('/movements',{method:'POST',body:JSON.stringify({product_id:payload.product_id,kind:'in',quantity:Number(payload.quantity)||1,note:'Devolução de locação'})});if(kind==='service'&&Number(String(payload?.f5||'').replace(',','.'))>0)await api('/finance',{method:'POST',body:JSON.stringify({description:`OS concluída · ${item.title}`,kind:'receive',category:'Serviços',amount:Number(String(payload.f5).replace(',','.'))})});await api(`/operations/${btn.dataset.operationDone}`,{method:'PUT',body:JSON.stringify({status:kind==='rental'?'returned':'done'})});showToast(kind==='rental'?'Devolução registrada':kind==='service'?'OS concluída · conta a receber registrada':kind==='shipping'?'Pedido despachado':'Registro concluído');await refreshOperationHistory(kind,container);await refreshProductTables();await refreshFinance()}catch(err){showToast(err.message)}}))}catch(e){}}
