function exportReport(report='Vendas por período'){Promise.all([api('/products'),api('/sales'),api('/finance')]).then(([products,sales,finance])=>{let header,rows;if(report==='Estoque'){header=['SKU','Produto','Categoria','Variação','Lote','Validade','Estoque','Mínimo','Preço'];rows=products.map(p=>[p.sku,p.name,p.category,p.variant,p.lot,p.expiry_date,p.stock,p.min_stock,p.price])}else if(report==='Financeiro'){header=['Descrição','Tipo','Vencimento','Categoria','Valor','Status'];rows=finance.map(f=>[f.description,f.kind,f.due_date,f.category,f.amount,f.status])}else{header=['Pedido','Cliente','Data','Canal','Total','Status'];rows=sales.map(x=>[x.number,x.customer,x.created_at,x.channel,x.total,x.status])}const csv=[header,...rows].map(row=>row.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=`nexoflow-${report.toLowerCase().replaceAll(' ','-')}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast(`${rows.length} registros exportados`) }).catch(err=>showToast(err.message))}
function money(value){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value)||0)}function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function barcodeMarkup(value,sku){let digits=String(value||'').replace(/\D/g,'');if(digits.length===12){let sum=0;for(let i=0;i<12;i++)sum+=Number(digits[i])*(i%2===0?1:3);digits+=String((10-sum%10)%10)}if(digits.length===13){let sum=0;for(let i=0;i<12;i++)sum+=Number(digits[i])*(i%2===0?1:3);if(String((10-sum%10)%10)!==digits[12])return `<span>EAN ${escapeHtml(digits)} · SKU ${escapeHtml(sku)}</span>`}if(digits.length!==13)return `<span>SKU ${escapeHtml(sku)}</span>`;const left=['0001101','0011001','0010011','0111101','0100011','0110001','0101111','0111011','0110111','0001011'],parity=['LLLLLL','LLGLGG','LLGGLG','LLGGGL','LGLLGG','LGGLLG','LGGGLL','LGLGLG','LGLGGL','LGGLGL'],right=left.map(x=>x.replace(/0/g,'x').replace(/1/g,'0').replace(/x/g,'1')),first=Number(digits[0]),mask=parity[first];let bits='101';for(let i=1;i<7;i++)bits+=(mask[i-1]==='L'?left:right)[Number(digits[i])];bits+='01010';for(let i=7;i<13;i++)bits+=right[Number(digits[i])];bits+='101';const bars=[...bits].map((b,i)=>b==='1'?`<rect x="${i}" y="0" width="1" height="46"/>`:'').join('');return `<svg viewBox="0 0 95 46" aria-label="EAN ${digits}" style="width:100%;height:12mm;fill:#111">${bars}</svg><span>${digits}</span>`}
function goToPage(name){if(name==='pos')name='new-pos';if(name==='users'&&currentUserRole&&!['Administrador','Administradora','Superadmin'].includes(currentUserRole)){name='overview';showToast('A área de usuários é restrita ao administrador da empresa')}if(!pageTitles[name])name='overview';allPages=document.querySelectorAll('.page');allPages.forEach(p=>p.classList.toggle('active-page',p.id===`page-${name}`));const navRoute={'new-pos':'pos','new-sale':'sales','new-product':'inventory','new-xml':'xml','new-finance':'finance','new-fiscal':'fiscal','new-channel':'integrations','report-builder':'reports'}[name]||name;navLinks.forEach(a=>a.classList.toggle('active',a.dataset.page===navRoute||['company','users','tax','api'].includes(name)&&a.dataset.page==='settings'));document.getElementById('crumb').textContent=pageTitles[name];history.replaceState(null,'',`#${name}`);document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
document.addEventListener('click',e=>{const pageEl=e.target.closest('[data-page]');if(pageEl){e.preventDefault();goToPage(pageEl.dataset.page)}const toastEl=e.target.closest('[data-toast]');if(toastEl){const label=`${toastEl.textContent} ${toastEl.dataset.toast}`.toLocaleLowerCase('pt-BR');const target=label.includes('novo pedido')?'new-sale':label.includes('novo produto')||label.includes('cadastro de produto')?'new-product':label.includes('lançamento financeiro')||label.includes('novo lançamento')?'new-finance':label.includes('emissão de nota')||label.includes('emitir documento')?'new-fiscal':label.includes('assistente de conexão')||label.includes('conectar canal')?'new-channel':label.includes('relatório exportado')||label.includes('exportar')?'report-builder':null;if(target)goToPage(target);else showToast(toastEl.dataset.toast)}});
