document.getElementById('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('bk-theme',document.body.classList.contains('dark')?'dark':'light')});if(localStorage.getItem('bk-theme')==='dark')document.body.classList.add('dark');
const modal=document.getElementById('modal'),commandInput=document.getElementById('commandInput'),commandResults=document.getElementById('commandResults');let selectedResult=0;
function renderResults(q=''){const query=q.toLocaleLowerCase('pt-BR');const items=Object.entries(pageTitles).filter(([id,title])=>`${id} ${title}`.toLocaleLowerCase('pt-BR').includes(query));commandResults.innerHTML=items.map(([id,title],i)=>`<button class="command-result ${i===selectedResult?'selected':''}" data-command-page="${id}"><span>◫</span>${title}<span>↵</span></button>`).join('')||'<div style="padding:12px;color:#9aa3af;font-size:10px">Nenhuma tela encontrada</div>';commandResults.querySelectorAll('[data-command-page]').forEach(b=>b.addEventListener('click',()=>{goToPage(b.dataset.commandPage);closeCommand()}))}
function openCommand(){modal.classList.add('open');commandInput.value='';selectedResult=0;renderResults();setTimeout(()=>commandInput.focus(),20)}function closeCommand(){modal.classList.remove('open')}
document.getElementById('globalSearch').addEventListener('click',openCommand);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='Escape')closeCommand();if(modal.classList.contains('open')&&e.key==='ArrowDown'){e.preventDefault();const items=commandResults.querySelectorAll('.command-result');if(items.length){selectedResult=(selectedResult+1)%items.length;renderResults(commandInput.value)}}if(modal.classList.contains('open')&&e.key==='ArrowUp'){e.preventDefault();const items=commandResults.querySelectorAll('.command-result');if(items.length){selectedResult=(selectedResult-1+items.length)%items.length;renderResults(commandInput.value)}}if(modal.classList.contains('open')&&e.key==='Enter'){commandResults.querySelector('.command-result.selected')?.click()}});
modal.addEventListener('click',e=>{if(e.target===modal)closeCommand()});commandInput.addEventListener('input',()=>{selectedResult=0;renderResults(commandInput.value)});
document.getElementById('navSearch').addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase('pt-BR');navLinks=[...document.querySelectorAll('.nav-item[data-page]')];navLinks.forEach(a=>{const group=a.closest('.nav-group');a.style.display=a.textContent.toLocaleLowerCase('pt-BR').includes(q)?'flex':'none';if(group)group.style.display=[...group.querySelectorAll('.nav-item')].some(item=>item.style.display!=='none')?'block':'none'})});
document.getElementById('quickAction').addEventListener('click',()=>{const menu=document.createElement('div');menu.className='quick-menu';menu.innerHTML='<button data-quick="sales">＋ Nova venda</button><button data-quick="inventory">▤ Novo produto</button><button data-quick="xml">⇧ Importar XML</button><button data-quick="finance">◉ Lançamento financeiro</button>';document.body.append(menu);const rect=document.getElementById('quickAction').getBoundingClientRect();menu.style.top=`${rect.bottom+7}px`;menu.style.right=`${Math.max(16,innerWidth-rect.right)}px`;menu.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>{goToPage(b.dataset.quick);menu.remove()}));setTimeout(()=>document.addEventListener('click',function close(ev){if(!menu.contains(ev.target)){menu.remove();document.removeEventListener('click',close)}},{once:true}),0)});
document.getElementById('dateFilter').addEventListener('click',()=>{const menu=document.createElement('div');menu.className='quick-menu';menu.innerHTML=['Últimos 7 dias','Últimos 30 dias','Este mês','Mês passado'].map(x=>`<button>${x}</button>`).join('');document.body.append(menu);const rect=document.getElementById('dateFilter').getBoundingClientRect();menu.style.top=`${rect.bottom+7}px`;menu.style.right=`${Math.max(16,innerWidth-rect.right)}px`;menu.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#dateFilter span').textContent=b.textContent;menu.remove();showToast(`Período: ${b.textContent}`)}));setTimeout(()=>document.addEventListener('click',function close(ev){if(!menu.contains(ev.target)){menu.remove();document.removeEventListener('click',close)}},{once:true}),0)});
document.getElementById('importXml').addEventListener('click',()=>document.getElementById('fileInput').click());document.getElementById('fileInput').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const result=await api('/xml/read',{method:'POST',body:JSON.stringify({filename:file.name,xml:await file.text()})});let form=document.querySelector('.active-page form');if(!form){goToPage('new-xml');form=document.querySelector('#page-new-xml form')}const active=form?.closest('.page');if(form){form.dataset.xmlId=result.id;form.dataset.xmlPayload=JSON.stringify(result.payload);const input=active.querySelector('.input-action input');if(input)input.value=file.name;const supplier=form.querySelector('[name="f1"]');if(supplier)supplier.value=result.payload.supplier||'Fornecedor não identificado';active.querySelector('.preview-total strong').textContent=money(result.payload.total)}await refreshXml();showToast(`XML lido: ${result.payload.items?.length||0} itens · ${result.payload.supplier||'fornecedor não identificado'}`)}catch(err){showToast(`Não foi possível ler o XML: ${err.message}`)}e.target.value=''});
async function refreshLiveDashboard(){
 try{
  const d=await api('/dashboard'),root=document.querySelector('#page-overview');if(!root)return;
  root.querySelector('[data-live-sales]').textContent=money(d.salesMonth);
  root.querySelector('[data-live-orders]').textContent=Number(d.ordersMonth||0).toLocaleString('pt-BR');
  root.querySelector('[data-live-ticket]').textContent=money(d.ticketAverage);
  root.querySelector('[data-live-low-stock]').innerHTML=`${Number(d.lowStock||0)} <small>produtos</small>`;
  const salesPage=document.querySelector('#page-sales');if(salesPage){salesPage.querySelector('[data-sales-today]').textContent=Number(d.salesTodayOrders||0).toLocaleString('pt-BR');salesPage.querySelector('[data-sales-quotes]').textContent=Number(d.quotesOpen||0).toLocaleString('pt-BR');salesPage.querySelector('[data-sales-month]').textContent=money(d.salesMonth);salesPage.querySelector('[data-sales-ticket]').textContent=money(d.ticketAverage)}
  const inventoryPage=document.querySelector('#page-inventory');if(inventoryPage){inventoryPage.querySelector('[data-inventory-products]').textContent=Number(d.products||0).toLocaleString('pt-BR');inventoryPage.querySelector('[data-inventory-cost]').textContent=money(d.inventoryCost);inventoryPage.querySelector('[data-inventory-low]').innerHTML=Number(d.lowStock||0)+' <small>produtos</small>';inventoryPage.querySelector('[data-inventory-movements]').textContent=Number(d.movementsToday||0).toLocaleString('pt-BR')}
  const financePage=document.querySelector('#page-finance');if(financePage){financePage.querySelector('[data-finance-receive]').textContent=money(d.receivableOpen);financePage.querySelector('[data-finance-pay]').textContent=money(d.payableOpen);financePage.querySelector('[data-finance-result]').textContent=money(Number(d.salesMonth||0)-Number(d.expensesPaidMonth||0))}
  const change=root.querySelector('[data-live-sales-change]');
  if(Number(d.salesPreviousMonth)>0){const pct=((Number(d.salesMonth)-Number(d.salesPreviousMonth))/Number(d.salesPreviousMonth))*100;change.textContent=`${pct>=0?'↑':'↓'} ${Math.abs(pct).toFixed(1).replace('.',',')}% vs. mês anterior`;change.className=`metric-foot trend ${pct>=0?'positive':'warning'}`}else change.textContent='Sem histórico do mês anterior';
  const series=Array.isArray(d.daily)?d.daily:[],values=series.map(x=>Number(x.revenue)||0),max=Math.max(1,...values),points=values.map((v,i)=>`${values.length<2?350:i*700/(values.length-1)},${190-(v/max)*170}`),line=points.length?`M${points.join(' L')}`:'M0 190 L700 190';
  const fill=root.querySelector('.chart-fill'),stroke=root.querySelector('.chart-stroke');if(fill)fill.setAttribute('d',`${line} L700 205 L0 205Z`);if(stroke)stroke.setAttribute('d',line);
  const chartTotal=values.reduce((a,b)=>a+b,0);root.querySelector('[data-live-chart-total]').textContent=money(chartTotal);
  root.querySelector('[data-live-chart-subtitle]').textContent=`Últimos 30 dias · ${series.reduce((n,x)=>n+Number(x.orders||0),0)} vendas registradas`;
  const y=root.querySelector('[data-live-chart-y]');if(y){const top=Math.ceil(max/4);y.innerHTML=[4,3,2,1,0].map(n=>`<span>${money(top*n)}</span>`).join('')}
  const xs=root.querySelector('[data-live-chart-x]');if(xs){const indexes=Array.from({length:7},(_,i)=>Math.round(i*Math.max(0,series.length-1)/6));xs.innerHTML=indexes.map(i=>`<span>${series[i]?.day?new Date(`${series[i].day}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'—'}</span>`).join('')}
  const channels=Array.isArray(d.channels)?d.channels:[],orders=channels.reduce((n,x)=>n+Number(x.orders||0),0),legend=root.querySelector('[data-live-channel-legend]'),donut=root.querySelector('.donut');
  root.querySelector('[data-live-channel-count]').textContent=orders.toLocaleString('pt-BR');
  if(legend){if(!channels.length){if(donut)donut.style.background='conic-gradient(#e8edf4 0 100%)';legend.innerHTML='<div class="empty-state">Sem vendas registradas neste mês.</div>'}else{const colors=['#536ff0','#8a6be0','#33a9c7','#36a77d','#d4a33e'];let start=0;const stops=channels.map((x,i)=>{const pct=orders?Number(x.orders)/orders*100:0;const stop=start+pct;const segment=`${colors[i%colors.length]} ${start}% ${stop}%`;start=stop;return segment});if(donut)donut.style.background=`conic-gradient(${stops.join(',')})`;legend.innerHTML=channels.map((x,i)=>`<div><i class="legend-dot" style="background:${colors[i%colors.length]}"></i><span>${escapeHtml(x.channel||'Canal não informado')}</span><strong>${orders?Math.round(Number(x.orders)/orders*100):0}%</strong></div>`).join('')}}
  const body=document.querySelector('#ordersBody');if(body)body.innerHTML=(d.recent||[]).map(x=>`<tr><td><strong class="order-id">#NF-${x.number}</strong></td><td>${escapeHtml(x.customer||'Consumidor final')}</td><td>${new Date(x.created_at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</td><td>${escapeHtml(x.channel||'PDV')}</td><td class="money">${money(x.total)}</td><td><span class="status-pill ${x.status==='quote'?'status-pending':'status-paid'}">● ${x.status==='quote'?'Orçamento':'Registrada'}</span></td></tr>`).join('')||'<tr><td colspan="6">Nenhuma venda registrada. As vendas realizadas aparecerão aqui.</td></tr>';
 }catch(e){const foot=document.querySelector('[data-live-sales-change]');if(foot)foot.textContent='Não foi possível carregar os dados agora.'}
}
const initial=location.hash.slice(1);if(pageTitles[initial])goToPage(initial);api('/health').then(async()=>{document.body.classList.add('server-online');const me=await api('/me');currentUserRole=me.role;const companyName=document.querySelector('[data-company-name]');if(companyName)companyName.textContent=me.company||'Sua empresa';const identity=document.querySelector('.user-card>span');if(identity){identity.querySelector('strong').textContent=me.name;identity.querySelector('small').textContent=me.company?`${me.role} · ${me.company}`:me.role}const initials=me.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const avatar=document.querySelector('.user-avatar');if(avatar)avatar.textContent=initials;const settingsLink=document.querySelector('.sidebar-bottom>a[data-page="settings"]');if(me.role==='Superadmin'){if(settingsLink)settingsLink.hidden=true;const admin=document.createElement('a');admin.className='nav-item';admin.href='/admin.html';admin.innerHTML='<span class="nav-icon">▦</span>Administração da plataforma';document.querySelector('.sidebar-bottom').insertBefore(admin,document.querySelector('.user-card'))}else if(!['Administrador','Administradora'].includes(me.role)){if(settingsLink)settingsLink.hidden=true}if(initial==='users'&&!['Administrador','Administradora','Superadmin'].includes(me.role))goToPage('overview');await Promise.all([refreshProductTables(),refreshFinance(),refreshSales(),refreshXml(),refreshLiveDashboard()]);}).catch(()=>document.body.classList.add('server-offline'));

document.querySelector('.more-button')?.addEventListener('click',async()=>{try{await api('/auth/logout',{method:'POST',body:JSON.stringify({})})}finally{location.href='/login.html'}});
document.addEventListener('input',e=>{if(e.target.matches('.table-search')){const q=e.target.value.toLocaleLowerCase('pt-BR');e.target.closest('.panel')?.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase('pt-BR').includes(q))}});
document.addEventListener('click',e=>{const status=e.target.closest('[data-status-filter]');if(status){const choices=['Todos os status','Pago','Orçamento'];const menu=document.createElement('div');menu.className='quick-menu';menu.innerHTML=choices.map(x=>`<button>${x}</button>`).join('');const r=status.getBoundingClientRect();menu.style.top=`${r.bottom+6}px`;menu.style.right=`${Math.max(16,innerWidth-r.right)}px`;document.body.append(menu);menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{const q=b.textContent==='Todos os status'?'':b.textContent.toLowerCase();document.querySelectorAll('#page-sales tbody tr').forEach(row=>row.hidden=!!q&&!row.textContent.toLowerCase().includes(q));status.textContent=b.textContent+'⌄';menu.remove()})}});

document.addEventListener('click',e=>{const filter=e.target.closest('.table-actions .button-light');if(filter&&!filter.hasAttribute('data-status-filter')){const label=filter.textContent.toLocaleLowerCase('pt-BR');const options=label.includes('filtro')?['Todos os produtos','Estoque baixo','Disponíveis']:label.includes('todas')?['Todas as notas','Conferir itens','Processadas']:label.includes('mês')?['Este mês','Próximos 30 dias','Vencidos']:null;if(options){const menu=document.createElement('div');menu.className='quick-menu';menu.innerHTML=options.map(x=>`<button>${x}</button>`).join('');const r=filter.getBoundingClientRect();menu.style.top=`${r.bottom+6}px`;menu.style.right=`${Math.max(16,innerWidth-r.right)}px`;document.body.append(menu);menu.querySelectorAll('button').forEach(b=>b.onclick=()=>{filter.textContent=b.textContent+'⌄';const q=b.textContent.toLocaleLowerCase('pt-BR');const table=filter.closest('.panel')?.querySelector('table');table?.querySelectorAll('tbody tr').forEach(row=>{const low=row.textContent.toLocaleLowerCase('pt-BR').includes('estoque baixo')||Number(row.querySelectorAll('td')[4]?.textContent)||0;row.hidden=q.includes('todos')?false:q.includes('baixo')?!String(row.textContent).toLowerCase().includes('estoque baixo'):q.includes('dispon')?String(row.textContent).toLowerCase().includes('disponível'):q.includes('conferir')?!String(row.textContent).toLowerCase().includes('processada'):q.includes('process')?!String(row.textContent).toLowerCase().includes('processada'):false});menu.remove()})}}});
document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();const field=document.querySelector('#page-new-pos.active-page [name="f0"]');field?.focus()}if(e.key==='Enter'&&document.activeElement?.matches('#page-new-pos [name="f0"]')){e.preventDefault();document.querySelector('#page-new-pos [data-module-action="add"]')?.click()}});
